0","oldProblemId":"3ab9a649-e0da-4542-875c-8a92ea893dea","newProblemId":"2d1dca1e-d2c1-494f-94bf-dbfc7518dbf4","moduleKey":"math_m1","route":null,"skill":"lines_angles_triangles","from":"easy","to":"hard","format":"mc"},{"section":"math","position":7,"oldVersionId":"034efb82-5d4f-4369-9cd8-00106556b7a8","oldProblemId":"cbec19e7-a402-4e68-bda0-ed9755cf5509","newProblemId":"d6b94d2e-4017-4568-8b77-45bb4eb2b931","moduleKey":"math_m1","route":null,"skill":"equivalent_expressions","from":"easy","to":"hard","format":"mc"},{"section":"math","position":36,"oldVersionId":"350583dc-f38a-4986-94bf-d5d955330c45","oldProblemId":"7b66a567-b8ea-4f5b-8c51-284aa6136548","newGid":"9e680a23-8330-5390-a020-3aa104081714","moduleKey":"math_m2","route":"lower","skill":"nonlinear_functions","from":"easy","to":"hard","format":"mc"},{"section":"math","position":38,"oldVersionId":"81a621bf-e14c-4177-870c-6e4d6decee1c","oldProblemId":"e812ef7c-4045-4e6a-82f4-e50cdfcf05aa","newGid":"e3e14de7-7a14-543e-a4f4-29fb818f4694","moduleKey":"math_m2","route":"lower","skill":"nonlinear_equations_systems","from":"easy","to":"hard","format":"mc"},{"section":"math","position":43,"oldVersionId":"2cb2e81f-6860-4d83-9aa6-91031cbc0dca","oldProblemId":"723ffd82-d9a1-45e2-8d1e-621f4883f877","newProblemId":"7bd09f9a-f3a8-47fe-abb6-4b49c5f38262","moduleKey":"math_m2","route":"lower","skill":"right_triangles_trigonometry","from":"easy","to":"hard","format":"mc"},{"section":"math","position":25,"oldVersionId":"f80582eb-63ef-4265-adcc-593497ee262f","oldProblemId":"9ab86311-c3d9-45e0-bdfe-1d86208a8b21","newProblemId":"c300963f-e2bc-44c7-b980-63c9a8676202","moduleKey":"math_m2","route":"lower","skill":"linear_equations_one_var","from":"easy","to":"hard","format":"mc"},{"section":"math","position":23,"oldVersionId":"967eebdd-866d-41b1-910f-90e4f1555abf","oldProblemId":"e0c7f6c8-4a9b-4a83-b873-2628b22055a5","newProblemId":"9aebc075-a8f2-4bec-bfac-0f332f69160b","moduleKey":"math_m2","route":"lower","skill":"evaluating_statistical_claims","from":"easy","to":"hard","format":"mc"}]}$satx$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1); v_src mock_exam_sets%rowtype; v_new uuid := gen_random_uuid(); v_cols text; v_cols_i text; sl jsonb; v_npid uuid; v_p problems%rowtype; v_it mock_exam_set_items%rowtype;
  v_slots int := 0; v_slotsj jsonb := '[]'::jsonb; v_bad text; v_np jsonb; v_hard_before int; v_hard_after int;
begin
  begin
    select * into v_src from mock_exam_sets where name = v_sp->>'name' and status = 'published' and archived_at is null for update;
    if v_src.id is null then raise exception 'published % not found', v_sp->>'name'; end if;
    -- 교체 칸 = 이 세트에서 아직 옛 문항(oldProblemId)인 칸
    for sl in select * from jsonb_array_elements(v_sp->'slots') loop
      select * into v_it from mock_exam_set_items i where i.exam_set_id = v_src.id and i.problem_id = (sl->>'oldProblemId')::uuid and i.module_key::text = sl->>'moduleKey' and coalesce(i.route::text, '') = coalesce(sl->>'route', '');
      if v_it.id is not null then v_slotsj := v_slotsj || jsonb_build_array(sl || jsonb_build_object('curSection', v_it.section, 'curPosition', v_it.position)); v_slots := v_slots + 1; end if;
    end loop;
    if v_slots = 0 then raise notice '% nothing to change (already up to date) - skipped', v_src.name; return; end if;
    if exists (select 1 from mock_exam_sets where set_group_id = v_src.set_group_id and status = 'draft') then raise notice '% a draft version already exists - skipped (publish/discard it, then re-run)', v_src.name; return; end if;
    perform pg_advisory_xact_lock(hashtextextended('mock_exam_new_version:' || v_src.set_group_id::text, 0));
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position) into v_cols from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_sets' and is_generated = 'NEVER' and column_name not in ('id', 'version_no', 'status', 'created_by', 'created_at', 'published_at', 'published_by', 'archived_at', 'access_tier', 'readiness_status', 'readiness_report', 'readiness_checked_at');
    execute format('insert into mock_exam_sets (id, version_no, status, created_by, access_tier, %s) select $1, $2, ''draft'', $3, ''tutoring'', %s from mock_exam_sets where id = $4', v_cols, v_cols)
      using v_new, (select max(version_no) + 1 from mock_exam_sets where set_group_id = v_src.set_group_id), v_actor, v_src.id;
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position), string_agg('i.' || quote_ident(column_name), ', ' order by ordinal_position)
      into v_cols, v_cols_i from information_schema.columns where table_schema = 'public' and table_name = 'mock_exam_set_items' and is_generated = 'NEVER' and column_name not in ('id', 'exam_set_id', 'created_at');
    execute format('insert into mock_exam_set_items (exam_set_id, %s) select $1, %s from mock_exam_set_items i where i.exam_set_id = $2
                    and not exists (select 1 from jsonb_to_recordset($3) as x("curSection" text, "curPosition" int) where x."curSection" = i.section and x."curPosition" = i.position)', v_cols, v_cols_i) using v_new, v_src.id, v_slotsj;
    for sl in select * from jsonb_array_elements(v_slotsj) loop
      v_npid := coalesce((sl->>'newProblemId')::uuid, (select problem_id from problem_versions where quality->'mockExamGeneration'->>'gid' = sl->>'newGid' limit 1));
      select * into v_p from problems where id = v_npid;
      if v_p.id is null or v_p.status <> 'confirmed' or v_p.archived_at is not null or v_p.published_version_id is null then raise exception 'replacement for slot %/% not usable (%)', sl->>'curSection', sl->>'curPosition', coalesce(sl->>'newGid', sl->>'newProblemId'); end if;
      if v_p.skill_code is distinct from sl->>'skill' or v_p.difficulty::text <> sl->>'to' or v_p.format::text <> sl->>'format' then raise exception 'replacement % does not match slot (skill/difficulty/format)', v_npid; end if;
      if exists (select 1 from mock_exam_set_items x where x.problem_id = v_npid and x.exam_set_id in (select id from mock_exam_sets where archived_at is null and status <> 'archived' and id <> v_new)) then raise exception 'replacement % already used in another live set', v_npid; end if;
      insert into mock_exam_set_items (exam_set_id, section, position, problem_id, problem_version_id, sat_domain, skill_code, difficulty, module_key, route)
      select v_new, i.section, i.position, v_npid, v_p.published_version_id, v_p.sat_domain, v_p.skill_code, v_p.difficulty, i.module_key, i.route from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'curSection' and i.position = (sl->>'curPosition')::int;
    end loop;
    -- 공식 문항 순서(Math: 스킬 공식 평균 위치 -> 난이도)로 모듈 안 position 재배치(position 값 집합은 그대로)
    select jsonb_agg(jsonb_build_object('id', np.id, 'pos', np.new_position)) into v_np from (
  with k as (select i.id, i.section, i.module_key, coalesce(i.route::text, '') as rt, i.position, coalesce(ord.ka, 99) as ka, coalesce(ord.kb, 0) as kb, case i.difficulty when 'easy' then 0 when 'medium' then 1 else 2 end as d
             from mock_exam_set_items i left join (values ('math','probability',3.5,0), ('math','inference_margin_error',8.3,0), ('math','evaluating_statistical_claims',8.3,0), ('math','two_variable_data',9.4,0), ('math','linear_equations_one_var',9.7,0), ('math','linear_functions',11.3,0), ('math','linear_inequalities',12.3,0), ('math','equivalent_expressions',13.2,0), ('math','ratios_rates_units',14.8,0), ('math','percentages',14.8,0), ('math','lines_angles_triangles',14.8,0), ('math','linear_equations_two_var',15.1,0), ('math','systems_linear',15.1,0), ('math','nonlinear_functions',15.6,0), ('math','one_variable_data',16.8,0), ('math','nonlinear_equations_systems',17.1,0), ('math','area_volume',17.1,0), ('math','right_triangles_trigonometry',19.1,0), ('math','circles',19.5,0)) as ord(section, skill, ka, kb) on ord.section = i.section and ord.skill = i.skill_code where i.exam_set_id = v_new and i.section = 'math'),
  a as (select k.*, row_number() over (partition by module_key, rt order by ka, kb, d, position) as orn, row_number() over (partition by module_key, rt order by position) as prn from k)
  select a.id, p.position as new_position from a join a p on p.module_key = a.module_key and p.rt = a.rt and p.prn = a.orn) np;
    update mock_exam_set_items set position = position + 100000 where exam_set_id = v_new and section = 'math';
    update mock_exam_set_items t set position = x.pos from jsonb_to_recordset(v_np) as x(id uuid, pos int) where t.id = x.id;
    select count(*) filter (where difficulty = 'hard') into v_hard_before from mock_exam_set_items where exam_set_id = v_src.id and section = 'math';
    select count(*) filter (where difficulty = 'hard') into v_hard_after from mock_exam_set_items where exam_set_id = v_new and section = 'math';
    if not coalesce((public.mock_exam_validate_mst_set(v_new)->>'ready')::boolean, false) then raise exception 'math hard5 set: 4-module/rule validation failed %', public.mock_exam_validate_mst_set(v_new)::text; end if;
    select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new) where issue is not null limit 5) x;
    if v_bad is not null then raise exception 'math hard5 set: item issues %', v_bad; end if;
    update mock_exam_sets set readiness_status = 'ready', readiness_report = public.mock_exam_validate_mst_set(v_new) || jsonb_build_object('shortfalls', '[]'::jsonb, 'checkedAt', now()), readiness_checked_at = now() where id = v_new;
    update mock_exam_sets set readiness_report = readiness_report || jsonb_build_object('mathHard5_1020', true) where id = v_new;
    raise notice '% new draft version created (% replaced slots, math hard % -> %) -> %', v_src.name, v_slots, v_hard_before, v_hard_after, v_new;
  exception when others then raise notice '% SKIPPED: %', v_sp->>'name', sqlerrm;
  end;
end
