84006","oldProblemId":"9954061f-44ab-453c-b044-01f05565b1b4","newProblemId":"6a7e7e63-3f7d-4ab5-a2c1-60b83dbfa7fc","moduleKey":"math_m1","route":null,"skill":"linear_equations_two_var","from":"easy","to":"hard","format":"mc"},{"section":"math","position":5,"oldVersionId":"98ca6568-3e6f-408f-a606-4d698ad6e8c5","oldProblemId":"a48288cb-3eb4-4637-8271-2c71d098496a","newProblemId":"bad2084f-8b5f-47a5-b48d-c21b45e777e8","moduleKey":"math_m1","route":null,"skill":"linear_functions","from":"easy","to":"hard","format":"mc"},{"section":"math","position":36,"oldVersionId":"abfd2b8e-0a5d-475c-a75b-30e77bc20d9c","oldProblemId":"48f6100f-6750-4cdd-afc1-a0a257eb408a","newGid":"f3fa333d-a200-5913-a870-190d62795790","moduleKey":"math_m2","route":"lower","skill":"nonlinear_functions","from":"easy","to":"hard","format":"spr"},{"section":"math","position":40,"oldVersionId":"1b4db3a9-3155-4df0-a1d1-0771d3c78c9c","oldProblemId":"74034e11-b157-45f0-ba7c-fdb6d736e32b","newGid":"ecb039b0-f937-582a-ab3d-4bee62d24cfa","moduleKey":"math_m2","route":"lower","skill":"nonlinear_equations_systems","from":"easy","to":"hard","format":"mc"},{"section":"math","position":39,"oldVersionId":"000411f0-c0c9-4102-ba59-3a5626994c2d","oldProblemId":"36f54287-738e-4655-b24f-d43431bc63b9","newProblemId":"627ad094-ba77-482c-93d2-48368f9bf1be","moduleKey":"math_m2","route":"lower","skill":"one_variable_data","from":"easy","to":"hard","format":"mc"},{"section":"math","position":41,"oldVersionId":"7e7e63f6-291b-404a-a82b-6cccd045ea72","oldProblemId":"87a3337f-92c7-4d63-ae12-f87cfcabaf3e","newProblemId":"be8caa17-b6fe-4f89-8f3f-36c17ed33c26","moduleKey":"math_m2","route":"lower","skill":"area_volume","from":"easy","to":"hard","format":"mc"},{"section":"math","position":28,"oldVersionId":"2712acaa-7041-4751-8723-7aa56662f01d","oldProblemId":"abc91565-e769-461e-8178-b3baa7c0f1c0","newProblemId":"bd5b4973-8fa6-493d-81da-6cdde10aa32c","moduleKey":"math_m2","route":"lower","skill":"linear_inequalities","from":"easy","to":"hard","format":"mc"}]}$satx$::jsonb;
  v_actor uuid := (select id from profiles where role = 'admin' order by created_at limit 1); v_src mock_exam_sets%rowtype; v_new uuid := gen_random_uuid(); v_cols text; v_cols_i text; sl jsonb; v_npid uuid; v_p problems%rowtype; v_it mock_exam_set_items%rowtype;
  v_slots int := 0; v_slotsj jsonb := '[]'::jsonb; v_bad text; v_np jsonb; v_hard_before int; v_hard_after int;
begin
  begin
    select * into v_src from mock_exam_sets where name = v_sp->>'name' and status = 'published' and archived_at is null for update;
    if v_src.id is null then raise exception 'published % not found', v_sp->>'name'; end if;
    -- 교체 칸 = 이 세트에서 아직 옛 문항(oldProblemId)인 칸
    for sl in select * from jsonb_array_elements(v_sp->'slots') loop
