    for sl in select * from jsonb_array_elements(v_slotsj) loop
      v_npid := coalesce((sl->>'newProblemId')::uuid, (select problem_id from problem_versions where quality->'mockExamGeneration'->>'gid' = sl->>'newGid' limit 1));
      select * into v_p from problems where id = v_npid;
      if v_p.id is null or v_p.status <> 'confirmed' or v_p.archived_at is not null or v_p.published_version_id is null then raise exception 'replacement for slot %/% not usable (%)', sl->>'curSection', sl->>'curPosition', coalesce(sl->>'newGid', sl->>'newProblemId'); end if;
      if v_p.skill_code is distinct from sl->>'skill' or v_p.difficulty::text <> sl->>'to' or v_p.format::text <> sl->>'format' then raise exception 'replacement % does not match slot (skill/difficulty/format)', v_npid; end if;
      if exists (select 1 from mock_exam_set_items x where x.problem_id = v_npid and x.exam_set_id in (select id from mock_exam_sets where archived_at is null and status <> 'archived' and id <> v_new)) then raise exception 'replacement % already used in another live set', v_npid; end if;
      insert into mock_exam_set_items (exam_set_id, section, position, problem_id, problem_version_id, sat_domain, skill_code, difficulty, module_key, route)
      select v_new, i.section, i.position, v_npid, v_p.published_version_id, v_p.sat_domain, v_p.skill_code, v_p.difficulty, i.module_key, i.route from mock_exam_set_items i where i.exam_set_id = v_src.id and i.section = sl->>'curSection' and i.position = (sl->>'curPosition')::int;
    end loop;
    -- 공식 문항 순서(Math: 스킬 공식 평균 위치 -> 난이도)로 모듈 안 position 재배치(position 값 집합은 그대로)
    select jsonb_agg(jsonb_build_object('id', np.id, 'pos', np.new_position)) into v_np from (
  with k as (select i.id, i.section, i.module_key, coalesce(i.route::text, '') as rt, i.position, coalesce(ord.ka, 99) as ka, coalesce(ord.kb, 0) as kb, case i.difficulty when 'easy' then 0 when 'medium' then 1 else 2 end as d
             from mock_exam_set_items i left join (values ('math','probability',3.5,0), ('math','inference_margin_error',8.3,0), ('math','evaluating_statistical_claims',8.3,0), ('math','two_variable_data',9.4,0), ('math','linear_equations_one_var',9.7,0), ('math','linear_functions',11.3,0), ('math','linear_inequalities',12.3,0), ('math','equivalent_expressions',13.2,0), ('math','ratios_rates_units',14.8,0), ('math','percentages',14.8,0), ('math','lines_angles_triangles',14.8,0), ('math','linear_equations_two_var',15.1,0), ('math','systems_linear',15.1,0), ('math','nonlinear_functions',15.6,0), ('math','one_variable_data',16.8,0), ('math','nonlinear_equations_systems',17.1,0), ('math','area_volume',17.1,0), ('math','right_triangles_trigonometry',19.1,0), ('math','circles',19.5,0)) as ord(section, skill, ka, kb) on ord.section = i.section and ord.skill = i.skill_code where i.exam_set_id = v_new and i.section = 'math'),
  a as (select k.*, row_number() over (partition by module_key, rt order by ka, kb, d, position) as orn, row_number() over (partition by module_key, rt order by position) as prn from k)
  select a.id, p.position as new_position from a join a p on p.module_key = a.module_key and p.rt = a.rt and p.prn = a.orn) np;
    update mock_exam_set_items set position = position + 100000 where exam_set_id = v_new and section = 'math';
    update mock_exam_set_items t set position = x.pos from jsonb_to_recordset(v_np) as x(id uuid, pos int) where t.id = x.id;
    select count(*) filter (where difficulty = 'hard') into v_hard_before from mock_exam_set_items where exam_set_id = v_src.id and section = 'math';
    select count(*) filter (where difficulty = 'hard') into v_hard_after from mock_exam_set_items where exam_set_id = v_new and section = 'math';
    if not coalesce((public.mock_exam_validate_mst_set(v_new)->>'ready')::boolean, false) then raise exception 'math hard5 set: 4-module/rule validation failed %', public.mock_exam_validate_mst_set(v_new)::text; end if;
    select string_agg(x.problem_id::text || ':' || x.issue, ', ') into v_bad from (select * from public.mock_exam_set_item_issues(v_new) where issue is not null limit 5) x;
    if v_bad is not null then raise exception 'math hard5 set: item issues %', v_bad; end if;
    update mock_exam_sets set readiness_status = 'ready', readiness_report = public.mock_exam_validate_mst_set(v_new) || jsonb_build_object('shortfalls', '[]'::jsonb, 'checkedAt', now()), readiness_checked_at = now() where id = v_new;
    update mock_exam_sets set readiness_report = readiness_report || jsonb_build_object('mathHard5_1020', true) where id = v_new;
    raise notice '% new draft version created (% replaced slots, math hard % -> %) -> %', v_src.name, v_slots, v_hard_before, v_hard_after, v_new;
  exception when others then raise notice '% SKIPPED: %', v_sp->>'name', sqlerrm;
  end;
end
